+import React, { FormEvent, useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [name, setName] = useState('');
+    const [savedName, setSavedName] = useState<string>();
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+    const visibleName = savedName ?? device.display_name ?? device.device_id;
+
+    const onSave = async (event: FormEvent) => {
+        event.preventDefault();
+        if (isSaving) return;
+        if (name === visibleName) {
+            setIsEditing(false);
+            return;
+        }
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, name);
+            setSavedName(name);
+            setIsEditing(false);
+        } catch (e) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (!isEditing) {
+        return <div data-testid='device-detail-heading'>
+            <Heading size='h3'>{ visibleName }</Heading>
+            <AccessibleButton
+                kind='link_inline'
+                data-testid='device-detail-rename'
+                onClick={() => {
+                    setName(visibleName);
+                    setError(undefined);
+                    setIsEditing(true);
+                }}
+            >{ _t('Rename') }</AccessibleButton>
+        </div>;
+    }
+
+    return <form data-testid='device-detail-heading-edit' onSubmit={onSave}>
+        <label htmlFor={`device-name-${device.device_id}`}>{ _t('Session name') }</label>
+        <input
+            id={`device-name-${device.device_id}`}
+            data-testid='device-detail-name-input'
+            value={name}
+            maxLength={100}
+            onChange={event => setName(event.target.value)}
+        />
+        <p>{ _t('Session names may be visible to people you communicate with.') }</p>
+        { error && <p role='alert' data-testid='device-detail-name-error'>{ error }</p> }
+        <button
+            type='submit'
+            data-testid='device-detail-name-save'
+            disabled={isSaving}
+        >
+            { _t('Save') } { isSaving && <Spinner w={16} h={16} /> }
+        </button>
+        <button
+            type='button'
+            data-testid='device-detail-name-cancel'
+            disabled={isSaving}
+            onClick={() => {
+                setIsEditing(false);
+                setError(undefined);
+            }}
+        >{ _t('Cancel') }</button>
+    </form>;
+};
